def merge_intervals(iv: list) -> list:
    if not iv:
        return []

    sorted_iv = sorted(iv, key=lambda x: x[0])
    merged = [sorted_iv[0][:]]

    for start, end in sorted_iv[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])

    return merged
```

